#!/usr/bin/env python3
import sys
import os
import re
import argparse
import difflib

def pattern_to_regex(pattern):
    tokens = re.findall(r'\$[A-Z_]+|[a-zA-Z0-9_]+|\s+|.', pattern)
    real_tokens = [t for t in tokens if not t.isspace()]
    seen_vars = set()
    regex_parts = []
    for t in real_tokens:
        if t.startswith('$') and len(t) > 1 and t[1:].isalpha():
            var = t[1:]
            if var not in seen_vars:
                regex_parts.append(f'(?P<{var}>.*?)')
                seen_vars.add(var)
            else:
                regex_parts.append(f'(?P={var})')
        elif t.isalnum():
            regex_parts.append(r'\b' + t + r'\b')
        else:
            regex_parts.append(re.escape(t))
    return r'\s*'.join(regex_parts)

def apply_rewrite(match, rewrite_pattern):
    def repl(m):
        var_name = m.group(1)
        try:
            return match.group(var_name)
        except IndexError:
            return m.group(0)
    return re.sub(r'\$([A-Z_]+)', repl, rewrite_pattern)

def main():
    argv = sys.argv[1:]
    if argv and argv[0] == "run":
        argv = argv[1:]

    parser = argparse.ArgumentParser()
    parser.add_argument("paths", nargs="*", default=["."])
    parser.add_argument("-p", "--pattern")
    parser.add_argument("-r", "--rewrite")
    parser.add_argument("-l", "--lang")
    parser.add_argument("-U", "--update-all", action="store_true")
    parser.add_argument("--color", default="auto")
    parser.add_argument("--heading", default="auto")
    parser.add_argument("-C", "--context", type=int, default=0)
    args, unknown = parser.parse_known_args(argv)

    if not args.pattern:
        sys.exit(2)

    regex_str = pattern_to_regex(args.pattern)
    try:
        re_pattern = re.compile(regex_str, re.DOTALL)
    except Exception:
        sys.exit(1)

    exts = ['.ts', '.js', '.tsx', '.jsx']

    files_to_search = []
    for p in args.paths:
        if os.path.isfile(p):
            files_to_search.append(p)
        elif os.path.isdir(p):
            for root, dirs, files in os.walk(p):
                for f in files:
                    if any(f.endswith(e) for e in exts):
                        files_to_search.append(os.path.join(root, f))

    total_changes = 0
    any_matches = False

    is_tty = sys.stdout.isatty()
    if args.heading == "auto":
        use_heading = is_tty
    elif args.heading == "always":
        use_heading = True
    else:
        use_heading = False

    for filepath in files_to_search:
        if not os.path.exists(filepath):
            continue
        with open(filepath, "r") as f:
            content = f.read()

        matches = list(re_pattern.finditer(content))
        if not matches:
            continue

        any_matches = True

        if args.rewrite:
            if args.update_all:
                new_content = content
                for m in reversed(matches):
                    replacement = apply_rewrite(m, args.rewrite)
                    new_content = new_content[:m.start()] + replacement + new_content[m.end():]
                with open(filepath, "w") as f:
                    f.write(new_content)
                total_changes += len(matches)
            else:
